<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driver\Rest\TenantConfigAllowController;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driver\Rest\TenantConfigListController;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driver\Rest\TenantConfigCreateController;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driver\Rest\TenantConfigRetrieveController;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driver\Rest\TenantConfigUpdateController;
use Civi\Lughauth\Features\Access\TenantConfig\Infrastructure\Driver\Rest\TenantConfigDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Service\Visibility\TenantConfigRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Service\Visibility\TenantConfigCollectNonEditableFields;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Usecase\Create\TenantConfigCreateAllowDecision;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Usecase\Update\TenantConfigUpdateAllowDecision;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Usecase\Retrieve\TenantConfigRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Usecase\List\TenantConfigListAllowDecision;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Access\TenantConfig\Application\Usecase\Delete\TenantConfigDeleteAllowDecision;

class TenantConfigPlugin extends MicroPlugin
{
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/tenants-config', [$this, 'setRoutesForTenantConfig']);
        $collector->group('/api/me/acl/access/tenants-config', [$this, 'setRoutesForTenantConfigAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $bus): void
    {
        $bus->registerListener(TenantConfigRestrictFilterToVisibility::class, TenantAccesible::class);
        $bus->registerListener(TenantConfigCollectNonEditableFields::class, FixTenantExcludingRoot::class);
        $bus->registerListener(TenantConfigCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $bus->registerListener(TenantConfigUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $bus->registerListener(TenantConfigRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $bus->registerListener(TenantConfigListAllowDecision::class, IsAuthenticatedListAllow::class);
        $bus->registerListener(TenantConfigDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("tenant-config", "list", "READ");
            $handler->registerResourceAction("tenant-config", "create", "WRITE");
            $handler->registerResourceAction("tenant-config", "retrieve", "READ");
            $handler->registerResourceAction("tenant-config", "update", "WRITE");
            $handler->registerResourceAction("tenant-config", "delete", "WRITE");

            $handler->registerResourceAttribute("tenant-config", "tenant", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "innerLabel", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "forceMfa", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "allowRegister", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "enableRegisterUsers", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "wellcomeEmail", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "registerdEmail", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "disabledUserEmail", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "enabledUserEmail", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "allowRecoverPass", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "recoverPassEmail", "MANAGE");
            $handler->registerResourceAttribute("tenant-config", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForTenantConfigAcl(RouteCollectorProxy $tenantConfigGroup): void
    {
        $tenantConfigGroup->get('', [TenantConfigAllowController::class, 'genericAllow']);
        $tenantConfigGroup->get('/{uid}', [TenantConfigAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForTenantConfig(RouteCollectorProxy $tenantConfigGroup): void
    {
        $tenantConfigGroup->get('', [TenantConfigListController::class, 'list']);
        $tenantConfigGroup->post('', [TenantConfigCreateController::class, 'create']);
        $tenantConfigGroup->get('/{uid}', [TenantConfigRetrieveController::class, 'retrieve']);
        $tenantConfigGroup->put('/{uid}', [TenantConfigUpdateController::class, 'update']);
        $tenantConfigGroup->delete('/{uid}', [TenantConfigDeleteController::class, 'delete']);
        $tenantConfigGroup->delete('', [TenantConfigDeleteController::class, 'deleteAllForQuery']);
        $tenantConfigGroup->get('/~/delete-status/{uid}', [TenantConfigDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
